def csv_write(path,rows,columns=None):
    if columns is None:columns=list(dict.fromkeys(k for r in rows for k in r))
    with path.open('w',encoding='utf8',newline='') as f:
        w=csv.DictWriter(f,fieldnames=columns,extrasaction='ignore');w.writeheader()
        for row in rows:w.writerow({k:json.dumps(v,separators=(',',':')) if isinstance(v,(dict,list)) else v for k,v in row.items()})
doc_rows=[json.loads(l) for l in (Path(doc['run'])/'raw.jsonl').read_text().splitlines()]
csv_write(report/'document-trials.csv',[{**r,'requiredReviewCount':r.get('validation',{}).get('requiredReviewCount')} for r in doc_rows],['index','scenario','mode','repeat','unsafeRetainedApprovals','incorrectNewCommits','partialEffectStates','unnecessaryReviewCount','requiredReviewCount','passed','infrastructureError','database'])
